  Future<String> confirm({required int proposalId}) => RustLib.instance.api
      .crateApiGlassesSessionConfirm(that: this, proposalId: proposalId);

  /// Etapa 1: descreve o ajuste. Nada é enviado ao óculos.
  Future<ProposalDto> prepare({required AdjustmentDto adjustment}) => RustLib
      .instance
      .api
      .crateApiGlassesSessionPrepare(that: this, adjustment: adjustment);

